CREATE TABLE user_knowledge_mastery (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, user_id BIGINT NOT NULL, kp_id BIGINT NOT NULL, profile_version BIGINT UNSIGNED NOT NULL, mastery_score DECIMAL(5,4) NOT NULL, confidence DECIMAL(5,4) NOT NULL, mastery_status VARCHAR(32) NOT NULL, evidence_count INT UNSIGNED NOT NULL DEFAULT 0, trend VARCHAR(16), algorithm_version VARCHAR(30) NOT NULL, window_start DATETIME(3), window_end DATETIME(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
 PRIMARY KEY(id), UNIQUE KEY uk_user_knowledge_mastery_user_kp(user_id,kp_id), KEY idx_user_knowledge_mastery_user_version(user_id,profile_version), KEY idx_user_knowledge_mastery_user_status(user_id,mastery_status), CONSTRAINT chk_ukm_user CHECK(user_id>0), CONSTRAINT chk_ukm_kp CHECK(kp_id>0), CONSTRAINT chk_ukm_score CHECK(mastery_score BETWEEN 0 AND 1), CONSTRAINT chk_ukm_confidence CHECK(confidence BETWEEN 0 AND 1), CONSTRAINT chk_ukm_status CHECK(mastery_status IN ('WEAK','CONSOLIDATING','BASIC_MASTERY','MASTERED','INSUFFICIENT_EVIDENCE')), CONSTRAINT chk_ukm_trend CHECK(trend IS NULL OR trend IN ('IMPROVING','STABLE','DECLINING')), CONSTRAINT chk_ukm_algorithm CHECK(algorithm_version<>''), CONSTRAINT chk_ukm_version CHECK(profile_version>=1), CONSTRAINT chk_ukm_window CHECK(window_start IS NULL OR window_end IS NULL OR window_start<=window_end)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
